INSERT INTO instancias (idx, prem, hyp, batch_name, source_file) VALUES
  (5704, $$El día de Navidad los niños golpeaban las puertas y visitaban los hogares, pidiendo y recibiendo dulces o juguetes chicos.$$, $$Los niños no se quedaron en casa el día de Navidad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5705, $$El día de Navidad los niños golpeaban las puertas y visitaban los hogares, pidiendo y recibiendo dulces o juguetes chicos.$$, $$El día de Navidad, los niños fueron al Polo Norte a visitar a Papá Noel.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5706, $$Los acertijos son tanto divertidos como educativos.$$, $$Los acertijos son aburridos y no te enseñan nada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5707, $$Los acertijos son tanto divertidos como educativos.$$, $$Los acertijos son dos cosas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5708, $$Los acertijos son tanto divertidos como educativos.$$, $$Los acertijos son muy difíciles de resolver.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5709, $$Esto no quiere decir que la buena arquitectura sea meramente utilitaria.$$, $$La buena arquitectura incluye la belleza estética, así como la función económica.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5710, $$Esto no quiere decir que la buena arquitectura sea meramente utilitaria.$$, $$Eso no quiere decir que la buena arquitectura esté diseñada únicamente de acuerdo con la funcionalidad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5711, $$Esto no quiere decir que la buena arquitectura sea meramente utilitaria.$$, $$El único atributo definitorio de la buena arquitectura es la utilidad.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5715, $$Claramente los niños de hoy pasan demasiadas horas frente al televisor, una circunstancia que restringe el tiempo disponible para actividades con los padres, jugar, leer y otras actividades que valen la pena.$$, $$Los niños de hoy pasan más tiempo viendo la TV que leyendo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5716, $$Claramente los niños de hoy pasan demasiadas horas frente al televisor, una circunstancia que restringe el tiempo disponible para actividades con los padres, jugar, leer y otras actividades que valen la pena.$$, $$La televisión no se ha inventado aún, por lo que la mayoría de los niños pasa mucho tiempo leyendo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5717, $$Claramente los niños de hoy pasan demasiadas horas frente al televisor, una circunstancia que restringe el tiempo disponible para actividades con los padres, jugar, leer y otras actividades que valen la pena.$$, $$Los niños de hoy tienen acceso a la televisión y pasan mucho tiempo viéndolo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5718, $$Deborah Lipstadt, en su libro Denying the Holocaust, escribió que no deberíamos hablar públicamente sobre afirmaciones inaceptables ni falsas, y por lo tanto propuso una solución tan poderosa como la censura gubernamental.$$, $$Lipstadt era cocinero.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5719, $$Deborah Lipstadt, en su libro Denying the Holocaust, escribió que no deberíamos hablar públicamente sobre afirmaciones inaceptables ni falsas, y por lo tanto propuso una solución tan poderosa como la censura gubernamental.$$, $$Lipstadt escribió un libro que obtuvo excelentes críticas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5720, $$Deborah Lipstadt, en su libro Denying the Holocaust, escribió que no deberíamos hablar públicamente sobre afirmaciones inaceptables ni falsas, y por lo tanto propuso una solución tan poderosa como la censura gubernamental.$$, $$Lipstadt escribió un libro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5721, $$Varios héroes populares tejanos, como Gregorio Cortez, Juan Cortina y Catarino Garza, se conmemoraron por sus confrontaciones con los Rangers de Texas.$$, $$Catarino Garza era un conocido Ranger de Texas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5722, $$Varios héroes populares tejanos, como Gregorio Cortez, Juan Cortina y Catarino Garza, se conmemoraron por sus confrontaciones con los Rangers de Texas.$$, $$Gregorio Cortez es uno de los héroes folclóricos que se enfrentó a los guardabosques de Texas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5723, $$Varios héroes populares tejanos, como Gregorio Cortez, Juan Cortina y Catarino Garza, se conmemoraron por sus confrontaciones con los Rangers de Texas.$$, $$Juan Cortina lideró el grupo que se enfrentó a los Texas Rangers.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5724, $$El momento de diseño para que padres e hijos estén juntos es el primer paso hacia la implementación de ideas y prácticas que comentaré en este libro.$$, $$Según este libro, los padres no deberían pasar tiempo con sus hijos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5725, $$El momento de diseño para que padres e hijos estén juntos es el primer paso hacia la implementación de ideas y prácticas que comentaré en este libro.$$, $$En este libro, trataré temas que los padres y sus hijos pueden poner en práctica mientras pasan tiempo juntos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5726, $$El momento de diseño para que padres e hijos estén juntos es el primer paso hacia la implementación de ideas y prácticas que comentaré en este libro.$$, $$Este libro para padres está en la lista de los más vendidos del New York Times.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5727, $$Una vez establecidas, las neuronas comienzan a asumir funciones únicas enviando ramificadores que forman conexiones elaboradas con otras neuronas.$$, $$Las neuronas establecidas se ramifican para formar conexiones con otras neuronas, lo que les permite realizar diversas funciones.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5728, $$Una vez establecidas, las neuronas comienzan a asumir funciones únicas enviando ramificadores que forman conexiones elaboradas con otras neuronas.$$, $$Las neuronas deben estar completamente establecidas antes de que puedan llevar a cabo ciertas funciones.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5729, $$Una vez establecidas, las neuronas comienzan a asumir funciones únicas enviando ramificadores que forman conexiones elaboradas con otras neuronas.$$, $$Las neuronas operan independientemente y no necesitan conectarse con otras neuronas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5730, $$15 El comandante quiere que hagamos algo y ha usado el lenguaje de la ley para que entremos en acción.$$, $$Si no fuera por la ley, habríamos desobedecido al comandante.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5731, $$15 El comandante quiere que hagamos algo y ha usado el lenguaje de la ley para que entremos en acción.$$, $$El comandante ha encontrado una manera de hacer que hagamos lo que él quiere.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5732, $$15 El comandante quiere que hagamos algo y ha usado el lenguaje de la ley para que entremos en acción.$$, $$El comandante sabe que nunca escucharemos nada de lo que dice.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5733, $$Relajo también puede describir una relación de broma, una broma de ida y vuelta, que a través de la risa alivia la tensión y desintegra la causa de la tensión del momento.$$, $$El relajo no es gracioso en absoluto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5734, $$Relajo también puede describir una relación de broma, una broma de ida y vuelta, que a través de la risa alivia la tensión y desintegra la causa de la tensión del momento.$$, $$Relajo hace bromas sobre la economía.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5735, $$Relajo también puede describir una relación de broma, una broma de ida y vuelta, que a través de la risa alivia la tensión y desintegra la causa de la tensión del momento.$$, $$Relajo contó chistes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5736, $$7), y aquellos con baja demanda (una media de 1300 unidades a la semana) y alta variación de demanda (Cv = 1,3).$$, $$Los grupos de baja y alta demanda se combinan en un total de veinte.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5737, $$7), y aquellos con baja demanda (una media de 1300 unidades a la semana) y alta variación de demanda (Cv = 1,3).$$, $$El grupo de baja demanda tiene un promedio de menos de trescientos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5738, $$7), y aquellos con baja demanda (una media de 1300 unidades a la semana) y alta variación de demanda (Cv = 1,3).$$, $$Hay dos grupos que se definen por la variación de la demanda.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5739, $$¿Debería ayudarla con las tareas? Y en ese caso, ¿cómo?$$, $$Debería preguntarle si necesita ayuda con las tareas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5741, $$¿Debería ayudarla con los deberes? Y en ese caso, ¿cómo?$$, $$No debería sentir la tentación de ayudarla con la tarea.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5742, $$Vea Wallis y Varjabedian para contemplar fotografías contemporáneas de antiguas moradas que todavía se encuentran en el norte de Nuevo México.$$, $$Las moradas ancestrales se pueden encontrar en la parte norte de Nuevo México.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5743, $$Vea Wallis y Varjabedian para contemplar fotografías contemporáneas de antiguas moradas que todavía se encuentran en el norte de Nuevo México.$$, $$No se conocen fotografías existentes de antiguas moradas en Nuevo México.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5744, $$Vea Wallis y Varjabedian para contemplar fotografías contemporáneas de antiguas moradas que todavía se encuentran en el norte de Nuevo México.$$, $$Wallis y Varjabedian proporcionan fotografías profesionales y coloridas de las antiguas Moradas de Nuevo México.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5745, $$La Vida de un Bato Loco, escrita por un informante de Linda Katz y reproducida en su obra, es un buen ejemplo de los usos literarios del caló.$$, $$Katz delató al comercio de la droga.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5746, $$La Vida de un Bato Loco, escrita por un informante de Linda Katz y reproducida en su obra, es un buen ejemplo de los usos literarios del caló.$$, $$Katz solo escribió sobre lo que otras personas hicieron.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5747, $$La Vida de un Bato Loco, escrita por un informante de Linda Katz y reproducida en su obra, es un buen ejemplo de los usos literarios del caló.$$, $$Linda Katz era una soplón.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5748, $$Las disputas tomaron el tono de una lucha de clase.$$, $$Peleaban por lo ricos que eran los directores ejecutivos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5749, $$Las disputas tomaron el tono de una lucha de clase.$$, $$Pelearon acerca de los pobres contra los ricos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5750, $$Las disputas tomaron el tono de una lucha de clase.$$, $$Se pelearon por el clima.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5751, $$Y es por eso que nos sentimos engañados por paredes huecas, puertas frágiles y barandillas temblorosas.$$, $$Las paredes huecas dejan entrar mucho ruido del parque.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5752, $$Y es por eso que nos sentimos engañados por paredes huecas, puertas frágiles y barandillas temblorosas.$$, $$Apreciamos las paredes huecas y las puertas endebles.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5753, $$Y es por eso que nos sentimos engañados por paredes huecas, puertas frágiles y barandillas temblorosas.$$, $$No estamos contentos con las paredes huecas y con las puertas frágiles.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5754, $$Lo que vemos son detalles.$$, $$En este momento no hay detalles disponibles.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5755, $$Lo que vemos son detalles.$$, $$Los detalles son visibles.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5756, $$Lo que vemos son detalles.$$, $$Los detalles han sido impresos en papel legal para que todos los vean.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5757, $$Él dirigió una apelación a San Martín.$$, $$Quería preguntarle algo a San Martín.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5758, $$Él dirigió una apelación a San Martín.$$, $$Quería pedirle a San Martín que perdonara a su esposa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5759, $$Él dirigió una apelación a San Martín.$$, $$San Martín no estaba a la vista.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5760, $$Jeremías Pitt respondió a la risa con una palabrota.$$, $$Jeremías Pitt respondió a la burla con una risita y lanzando un gancho hacia la cara del hombre que se reía.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5761, $$Jeremías Pitt respondió a la risa con una palabrota.$$, $$Jeremías Pitt juró luchar por su país y su reina.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5762, $$Jeremías Pérez respondió a la risa con una palabrota.$$, $$Alguien se rió cerca de Jeremías Pérez.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5763, $$Pedro, que observó la escena desde la barandilla de cubierta, nos dice que Su Excelencia tenía la voz tan grave como un pastor de un ahorcamiento.$$, $$Pedro nunca había visto a Su Excelencia tan seria como estaba entonces.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5764, $$Pedro, que observó la escena desde la barandilla de la toldilla, nos dice que mi General tenía la voz tan grave como un pastor de un ahorcamiento.$$, $$Pedro juró que no pudo vislumbrar la escena.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5765, $$Pedro, que observó la escena desde la barandilla del alcázar, nos dice que Su Excelencia tenía la voz tan grave como un pastor de un ahorcamiento.$$, $$Pedro fue testigo de cómo Su Excelencia hablaba en serio durante la escena.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5766, $$El Coronel lo aceptó, y se inclinó con demora, quitándose su amplio sombrero.$$, $$El Coronel aceptó una medalla del alcalde de la ciudad de Nueva York.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5767, $$El Coronel lo aceptó, y se inclinó con demora, quitándose su amplio sombrero.$$, $$El coronel rechazó lo que le daban y conservó su sombrero en señal de desafío.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5768, $$El Coronel Rodríguez lo aceptó, y se inclinó con demora, quitándose su amplio sombrero.$$, $$El coronel Rodríguez llevaba un sombrero.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5772, $$Se le permitió percibir que era al elegante y apuesto joven de Corrientes, Don José de San Martín, a quien ella dedicaba cada momento de su tiempo.$$, $$San Martín es de Corrientes.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5773, $$Se le permitió percibir que era al elegante y apuesto joven de St. James, San Martín, a quien ella dedicaba cada momento de su tiempo.$$, $$Ella y San Martín compartieron un beso anoche.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5774, $$Se le permitió percibir que era al elegante y apuesto joven de Buenos Aires, Don José de San Martín, a quien ella dedicaba cada momento de su tiempo.$$, $$Está encaprichada con Don José de San Martín, a pesar de su naturaleza torpe.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5775, $$¿Pero... pero... a bordo de este barco...? El oficial hizo un gesto de impotencia y, rindiéndose a su desconcierto, se calló abruptamente.$$, $$El oficial gritó durante minutos, enfurecido por la perversión de sus cubiertas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5776, $$¿Pero... pero... a bordo de este barco...? El oficial hizo un gesto de impotencia y, rindiéndose a su desconcierto, se calló abruptamente.$$, $$El oficial estaba confundido por lo que estaba sucediendo a bordo del barco.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5777, $$¿Pero... pero... a bordo de este barco...? El oficial hizo un gesto de impotencia y, rindiéndose a su desconcierto, se calló abruptamente.$$, $$El oficial quedó estupefacto por los vómitos en la cubierta$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5778, $$Sos San Martín, tengo entendido, fue su saludo truculento.$$, $$San Martín brindó un cálido y acogedor recibimiento.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5779, $$Sos Don José de San Martín, tengo entendido, fue su saludo truculento.$$, $$Don José de San Martín dio la bienvenida a los demás de una manera que se consideraría truculento.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5780, $$Sos San Martín, tengo entendido, fue su saludo truculento.$$, $$Aunque muchos habían intentado acercarse a él, San Martín era a menudo frío y sin emoción.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5781, $$Mary Traill te lo contaría.$$, $$Mary Traill puede contarte sobre el burro.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5782, $$María Traill te lo contaría.$$, $$María Traill sabe todo acerca del asunto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5783, $$María Traill te lo contaría.$$, $$Solo yo sé sobre esto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5784, $$Hay una horca esperando a este granuja en Buenos Aires. Bouchard habría intervenido, pero San Martín se lo impidió.$$, $$Bouchard es una organización criminal internacional con sede en Buenos Aires que San Martín contrata con fines ilícitos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5785, $$Hay una horca esperando a este granuja en Buenos Aires. Bouchard habría intervenido, pero San Martín se lo impidió.$$, $$Entre los dominios de San Martín está Buenos Aires, una ciudad comercial que es un centro de actividades de la región.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5786, $$Hay una horca esperando a este granuja en Buenos Aires. Bouchard habría intervenido, pero San Martín se lo impidió.$$, $$Buenos Aires tiene instalaciones para castigar criminales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5787, $$No será Rodríguez, dijo López, entre una pregunta y una aseveración.$$, $$López había hecho una pregunta que demostraba su asertividad a los demás.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5788, $$No será Rodríguez, dijo López, entre una pregunta y una aseveración.$$, $$López había mencionado al Rodríguez que era uno que era muy bonito.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5789, $$No será Coronel Rodríguez, dijo López, entre una pregunta y una aseveración.$$, $$López nunca dijo nada sobre el Coronel Rodríguez.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5790, $$¿Dejarás de hablar de motín y traición y consejo de guerra? Bouchard se puso su sombrero, y se sentó sin invitación.$$, $$Bouchard tenía un sombrero que llevaba puesto antes de sentarse.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5791, $$¿Dejarás de hablar de motín y traición y consejo de guerra? Bouchard se puso su sombrero, y se sentó sin invitación.$$, $$Bouchard se puso el sombrero y salió de la habitación sin decir nada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5792, $$¿Dejarás de hablar de motín y traición y consejo de guerra? Bouchard se puso su sombrero, y se sentó sin invitación.$$, $$El sombrero de Bouchard era negro, con tres plumas de águila.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5793, $$Las cosas no le habían ido nada bien en los últimos quince días desde que aceptó la comisión del Rey.$$, $$Durmió profundamente por la noche sabiendo que había rechazado el encargo del Rey.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5794, $$Las cosas no le habían ido nada bien en los últimos quince días desde que aceptó la comisión del Rey.$$, $$Mantenerlo despierto por la noche era el hecho de que él aceptaba la comisión del Rey.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5795, $$Las cosas no le habían ido nada bien en los últimos quince días desde que aceptó la comisión del Rey.$$, $$La comisión del Rey era un título muy prestigioso con muchas responsabilidades.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5796, $$Están dentro del alcance, gritó González.$$, $$González dijo que eran accesibles.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5797, $$Están dentro del alcance, gritó González.$$, $$González dijo que estaban al alcance del oído.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5798, $$Están dentro del alcance, gritó González.$$, $$Aunque sabía que estaban dentro del alcance, González se lo guardó para sí mismo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5799, $$Mandé a buscarlo a usted, Capitán Bouchard, debido a ciertas noticias que me acaban de llegar.$$, $$No escuché ninguna noticia, Capitán Bouchard. ¿Tenés?$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5802, $$¿Por qué corrés, entonces? Le preguntó fríamente, de pie, delgado y derecho ante él, todo en blanco y muy virginal excepto en su compostura antinatural.$$, $$Su postura no se veía natural porque tenía dolor de espalda$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5803, $$¿Por qué corrés, entonces? Le preguntó fríamente, de pie, delgado y derecho ante él, todo en blanco y muy virginal excepto en su compostura antinatural.$$, $$Ella no preguntó nada, ella le dijo que se fuera.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5804, $$¿Por qué corrés, entonces? Le preguntó fríamente, de pie, delgado y derecho ante él, todo en blanco y muy virginal excepto en su compostura antinatural.$$, $$Estaba vestida de blanco cuando preguntó: ¿Por qué corrés, entonces?.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5805, $$Regresarás a él de inmediato, y llevarás a tu tripulación con vos, o de lo contrario... Pero González, violento de apariencia y gestos, lo interrumpió.$$, $$González tenía una tripulación.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5806, $$Regresarás a él de inmediato, y llevarás a tu tripulación con vos, o de lo contrario... Pero González, violento de apariencia y gestos, lo interrumpió.$$, $$González le dejó continuar hablando.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5807, $$Regresarás a él de inmediato, y llevarás a tu tripulación con vos, o de lo contrario... Pero González, violento de apariencia y gestos, lo interrumpió.$$, $$González estaba enojado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5808, $$Bueno, bueno, tal vez no me encuentre tan fácil de entender como se imagina.$$, $$Nunca imaginó que me entendería.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5809, $$Bueno, bueno, tal vez no me encuentre tan fácil de entender como se imagina.$$, $$Piensa que agarrarme será realmente simple.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5810, $$Bueno, bueno, tal vez no me encuentre tan fácil de entender como se imagina.$$, $$Puede que no sea tan fácil de atrapar como él piensa.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5811, $$No pienses que lo acepto de buena gana.$$, $$Lo acepto de buena gana.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5812, $$No pienses que lo acepto de buena gana.$$, $$No estoy dispuesto a aceptarlo, pero podría estar convencido.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
