  (5814, $$Un asesino, ¿yo? dijo al fin.$$, $$Tras una pausa él dijo: Un asesino, yo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5815, $$Un asesino, ¿yo? dijo al fin.$$, $$Él no había asesinado a nadie.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5816, $$Un asesino, ¿yo? dijo al fin.$$, $$Inmediatamente dijo: Un asesino, yo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5817, $$Cuidadosamente acarició su barba dorada.$$, $$Él tenía una barba que era de color dorado.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5818, $$Cuidadosamente acarició su barba dorada.$$, $$Se había dejado crecer la barba durante años.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5819, $$Cuidadosamente acarició su barba dorada.$$, $$Su cara estaba bien afeitada.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5823, $$¿Qué mejor manera?, demandó.$$, $$No hizo ninguna pregunta, ya que sabía que había escogido la mejor manera.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5824, $$¿Qué mejor manera?, demandó.$$, $$Él quería saber si no había una mejor manera.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5825, $$¿Qué mejor manera?, demandó.$$, $$Estaba convencido de que había elegido la mejor manera.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5826, $$No se molestó en levantarse, ni siquiera cuando San Martín, obedeciendo a los instintos de una mejor crianza, le dio ejemplo.$$, $$Se levantó rápidamente y procedió a levantar a San Martín.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5827, $$No se molestó en levantarse, ni siquiera cuando San Martín, obedeciendo a los instintos de una mejor crianza, le dio ejemplo.$$, $$Se sentía muy cansado, así que no se levantó.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5828, $$No se molestó en levantarse, ni siquiera cuando Don José de San Martín, obedeciendo a los instintos de una mejor crianza, le dio ejemplo.$$, $$Don José de San Martín se levantó, mostrando buenos modales, pero no se molestó en ponerse de pie.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5829, $$La vida puede ser endemoniadamente compleja, suspiró.$$, $$Él dejó escapar un signo de resignación.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5830, $$La vida puede ser endemoniadamente compleja, suspiró.$$, $$Él permaneció en silencio de la misma manera que él se quejó de la simplicidad de la vida.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5831, $$La vida puede ser endemoniadamente compleja, suspiró.$$, $$La vida es infernalmente complicada debido a las muchas interacciones que uno puede tener.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5832, $$López se puso firme desafiante ante su capitán. Veré al coronel Rodríguez en el infierno o si alguna vez miento por él. Y escupió, seguramente con el objetivo de poner énfasis.$$, $$El Coronel Rodríguez ha hecho algo para convertir a López en su enemigo.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5833, $$López se puso firme desafiante ante su capitán. Veré al coronel Rodríguez en el infierno o si alguna vez miento por él. Y escupió, seguramente con el objetivo de poner énfasis.$$, $$Escupió en el suelo para destacar su punto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5834, $$López se puso firme desafiante ante su capitán. Veré al coronel Rodríguez en el infierno o si alguna vez miento por el. Y escupió, seguramente con el objetivo de poner énfasis.$$, $$López y el coronel Rodríguez eran amigos íntimos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5835, $$Yo ... creo que lo ha hecho, dijo Calderón, entre la duda y la sospecha.$$, $$Calderón respondió de una manera que parecía como si tuviera dudas.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5836, $$Yo ... creo que lo hizo, dijo Calderón, entre la duda y la sospecha.$$, $$Calderón solo fue indeciso en su respuesta porque no conocía todos los hechos.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5837, $$Yo ... creo que lo ha hecho, dijo Calderón, entre la duda y la sospecha.$$, $$Habló inteligentemente y claramente decidido ya que sabía que estaba en lo cierto.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5838, $$Y aunque se atreva a intentarlo, asegurate de que sus propios oficiales no se atrevan a hacer otra cosa que oponerse a él.$$, $$Él tiene sus propios oficiales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5839, $$Y aunque se atreva a intentarlo, asegurate de que sus propios oficiales no se atrevan a hacer otra cosa que oponerse a él.$$, $$Él está solo y no tiene oficiales.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
  (5840, $$Y aunque se atreva a intentarlo, asegurate de que sus propios oficiales no se atrevan a hacer otra cosa que oponerse a él.$$, $$Sus oficiales le respetan.$$, $$xnli_rp_full_2026-05-27$$, $$validation_app\to_upload\chunk_04.jsonl$$),
